#!/usr/bin/env python3
"""The hand-made mutants of work package S2.5 (prefix s25_): single-site changes of the navigation side: the navigation pack (the 32-bit and the long kernel of the suffix link, PSI and its verification, the inverse suffix array and PackHeapLimit,
   InPlaceFrom, Parent, Lcp, Lca), the 64-bit pyramid and the persisted RMQ levels, the 32-bit pyramid (FromLevels, the level sizes, the 64-bit members), the long navigator, the navigator of the generic algorithms over any index, the RMQ writer and its
   placement, the reading of the RMQ entry of a container, and the vetting of suffix array entries. Every `long` to `int` narrowing, every off-by-one at a section end and at 2^31 - 1 / 2^31 / 2^32 - 4, the fanout arithmetic of the pyramid, the block
   boundary of the levels, the arguments of the suffix link LCA(Psi(lb), Psi(rb)), the comparison of PackHeapLimit and InPlaceFrom at the limit and one above it, the padding of the 5-byte sections is a mutant. Writes s25_listed.json (the list that
   run_s25_mutants.py runs) and checks that every `old` text occurs exactly once in its file.
   usage: make_s25_mutants.py <repo root> <out.json>"""
import json, sys

ROOT = sys.argv[1]
OUT = sys.argv[2]
S = 'src/SuffixTree/Algorithms/SuffixTree.Esa/'
T = 'FullyQualifiedName~SuffixTree.Esa.Tests.'
F_PACK = '(' + T + 'Navigation.ContainerPackTests|' + T + 'Navigation.WideNavigationTests|' + T + 'Navigation.PackHeapLimitTests|' + T + 'Large.NavigationGeneratedTests)'
F_PYR = '(' + T + 'Views.LcpPyramidWideTests|' + T + 'Navigation.LcpPyramidTests|' + T + 'Large.NavigationGeneratedTests|' + T + 'Navigation.ContainerPackTests)'
F_RMQ = '(' + T + 'External.RmqWriterTests|' + T + 'Navigation.ContainerPackTests)'
F_NAV = '(' + T + 'Large.NavigationGeneratedTests|' + T + 'Navigation.WideNavigationTests|' + T + 'Search.WideIndexTests)'
F_WIDEMATCH = '(' + T + 'Navigation.WideMatchingTests|' + T + 'Navigation.WideNavigationTests)'
F_FILE = '(' + T + 'Navigation.ContainerPackTests|' + T + 'External.RmqWriterTests|' + T + 'Search.WideDamageSweepTests)'
F_SUPPORT = '(' + T + 'Navigation.PackHeapLimitTests|' + T + 'Contract.|' + T + 'Navigation.ContainerPackTests)'
STAGE3 = '(' + T + 'Large.NavigationGeneratedLargeTests|' + T + 'Large.NavigationSparseLargeTests)'
M = []


def m(id_, desc, file, old, new, filt, stage3=None):
    M.append({'id': 's25_' + id_, 'desc': desc, 'file': S + file, 'old': old, 'new': new, 'filter': filt, 'stage3': stage3 or STAGE3})


P = 'EsaNavigationPack.cs'
# ---- the long kernel of the suffix link
m('P01', 'the long link of a node of depth 1 is the node of depth 0 (t == 0 test off by one)', P, 'long t = node.Depth - 1;\n        if (t == 0) return Root64;', 'long t = node.Depth - 1;\n        if (t == 1) return Root64;', F_PACK)
m('P02', 'the long link takes the endpoint a from the right bound', P, 'long a = Psi(node.Lb, "the suffix link");\n        long b = Psi(node.Rb, "the suffix link");', 'long a = Psi(node.Rb, "the suffix link");\n        long b = Psi(node.Rb, "the suffix link");', F_PACK)
m('P03', 'the long link takes the endpoint b from the left bound', P, 'long a = Psi(node.Lb, "the suffix link");\n        long b = Psi(node.Rb, "the suffix link");', 'long a = Psi(node.Lb, "the suffix link");\n        long b = Psi(node.Lb, "the suffix link");', F_PACK)
m('P04', 'the long link searches the borders with the node depth instead of depth - 1', P, '_ranges.Borders(a, b, t, out long left, out long right, out long leftValue, out long rightValue);\n        long parentDepth', '_ranges.Borders(a, b, node.Depth, out long left, out long right, out long leftValue, out long rightValue);\n        long parentDepth', F_PACK)
m('P05', 'the long link ends the interval at the right border instead of one before it', P, 'return new EsaNode64(left, right - 1, t, parentDepth, target, leftValue > rightValue);', 'return new EsaNode64(left, right, t, parentDepth, target, leftValue > rightValue);', F_PACK)
m('P06', 'the long link takes the parent depth as the smaller border value', P, 'long parentDepth = Math.Max(leftValue, rightValue);\n        if (_mapped && (parentDepth >= t || left < 0 || left > _n)) throw DamagedNode();', 'long parentDepth = Math.Min(leftValue, rightValue);\n        if (_mapped && (parentDepth >= t || left < 0 || left > _n)) throw DamagedNode();', F_PACK)
m('P07', 'the long link flags the wrong child as the last', P, 'return new EsaNode64(left, right - 1, t, parentDepth, target, leftValue > rightValue);', 'return new EsaNode64(left, right - 1, t, parentDepth, target, leftValue < rightValue);', F_PACK)
m('P08', 'the long link gives the Pos of the right bound', P, 'long target = _sa64[left];\n        if (_mapped && (ulong)target > (ulong)_n) throw DamagedNode();\n        return new EsaNode64(left, right - 1, t', 'long target = _sa64[left + 1];\n        if (_mapped && (ulong)target > (ulong)_n) throw DamagedNode();\n        return new EsaNode64(left, right - 1, t', F_PACK)
m('P09', 'Checked: the endpoint a equal to n + 1 passes (the bound is one too wide)', P, 'if (_mapped && (a > _n || b < a || b > _n)) throw DamagedNode();', 'if (_mapped && (a > _n + 1 || b < a || b > _n)) throw DamagedNode();', F_PACK)
m('P10', 'Checked: b below a passes', P, 'if (_mapped && (a > _n || b < a || b > _n)) throw DamagedNode();', 'if (_mapped && (a > _n || b < a - 1 || b > _n)) throw DamagedNode();', F_PACK)
m('P11', 'Checked: the verification of the endpoint a compares with the position itself', P, 'if (_verifyPsi && (_sa64[a] != node.Pos + 1 || _sa64[b] != _sa64[node.Rb] + 1)) throw DamagedNode();', 'if (_verifyPsi && (_sa64[a] != node.Pos || _sa64[b] != _sa64[node.Rb] + 1)) throw DamagedNode();', F_PACK)
m('P12', 'Checked: the verification of the endpoint b is not made', P, 'if (_verifyPsi && (_sa64[a] != node.Pos + 1 || _sa64[b] != _sa64[node.Rb] + 1)) throw DamagedNode();', 'if (_verifyPsi && (_sa64[a] != node.Pos + 1)) throw DamagedNode();', F_PACK)
m('P13', 'Checked: the verification of the endpoint a is not made', P, 'if (_verifyPsi && (_sa64[a] != node.Pos + 1 || _sa64[b] != _sa64[node.Rb] + 1)) throw DamagedNode();', 'if (_verifyPsi && (_sa64[b] != _sa64[node.Rb] + 1)) throw DamagedNode();', F_PACK)
m('P14', 'Checked: a parent depth equal to t passes', P, 'if (_mapped && (parentDepth >= t || left < 0 || left > _n)) throw DamagedNode();', 'if (_mapped && (parentDepth > t || left < 0 || left > _n)) throw DamagedNode();', F_PACK)
m('P15', 'Checked: a left border of -1 passes', P, 'if (_mapped && (parentDepth >= t || left < 0 || left > _n)) throw DamagedNode();', 'if (_mapped && (parentDepth >= t || left < -1 || left > _n)) throw DamagedNode();', F_PACK)
m('P16', 'Checked: the target position n + 1 passes', P, 'long target = _sa64[left];\n        if (_mapped && (ulong)target > (ulong)_n) throw DamagedNode();', 'long target = _sa64[left];\n        if (_mapped && (ulong)target > (ulong)_n + 1) throw DamagedNode();', F_PACK)
# ---- the long leaf link
m('P20', 'the long leaf link of the last suffix (position n - 1) is not the root', P, 'long position = leaf.Pos;\n        if (position >= _n) return Root64;', 'long position = leaf.Pos;\n        if (position > _n) return Root64;', F_PACK)
m('P21', 'the long leaf link has the depth of the leaf', P, 'return new EsaNode64(rank, rank, leaf.Depth - 1, Math.Max(left, right), position + 1, left > right);', 'return new EsaNode64(rank, rank, leaf.Depth, Math.Max(left, right), position + 1, left > right);', F_PACK)
m('P22', 'the long leaf link has the position of the leaf', P, 'return new EsaNode64(rank, rank, leaf.Depth - 1, Math.Max(left, right), position + 1, left > right);', 'return new EsaNode64(rank, rank, leaf.Depth - 1, Math.Max(left, right), position, left > right);', F_PACK)
m('P23', 'the long leaf link reads the value after the last rank', P, 'long right = rank < _n ? _ranges.ValueAt(rank + 1) : -1;', 'long right = rank <= _n ? _ranges.ValueAt(rank + 1) : -1;', F_PACK)
m('P24', 'the long leaf link: the last-child flag is reversed', P, 'return new EsaNode64(rank, rank, leaf.Depth - 1, Math.Max(left, right), position + 1, left > right);', 'return new EsaNode64(rank, rank, leaf.Depth - 1, Math.Max(left, right), position + 1, left < right);', F_PACK)
m('P25', 'Checked: the leaf endpoint is not verified against the suffix array', P, 'if (_verifyPsi && _sa64[rank] != position + 1) throw DamagedNode();', '', F_PACK)
# ---- Psi, ISA, the limit
m('P30', 'Psi of the empty suffix reads the array', P, 'if (position >= _n) return 0;\n        if (position < 0 || position + 1 > _n) throw DamagedNode();', 'if (position > _n) return 0;\n        if (position < 0 || position + 1 > _n) throw DamagedNode();', F_PACK)
m('P31', 'Psi reads ISA at the position itself', P, 'return Isa(position + 1, member);', 'return Isa(position, member);', F_PACK)
m('P32', 'Psi of a rank above n is not refused', P, 'if ((ulong)rank > (ulong)_n) throw _mapped ? DamagedNode() : new ArgumentOutOfRangeException(nameof(rank));', 'if ((ulong)rank > (ulong)_n + 1) throw _mapped ? DamagedNode() : new ArgumentOutOfRangeException(nameof(rank));', F_PACK)
m('P33', 'the limit: a container of exactly PackHeapLimit symbols is refused', P, 'if (_mapped && _n > PackHeapLimit)\n            throw new NotSupportedException($"{member} needs', 'if (_mapped && _n >= PackHeapLimit)\n            throw new NotSupportedException($"{member} needs', F_PACK)
m('P34', 'the limit: a container of PackHeapLimit + 1 symbols is not refused', P, 'if (_mapped && _n > PackHeapLimit)\n            throw new NotSupportedException($"{member} needs', 'if (_mapped && _n > PackHeapLimit + 1)\n            throw new NotSupportedException($"{member} needs', F_PACK)
m('P35', 'the limit applies to an index in memory too', P, 'if (_mapped && _n > PackHeapLimit)\n            throw new NotSupportedException($"{member} needs', 'if (_n > PackHeapLimit)\n            throw new NotSupportedException($"{member} needs', F_PACK)
m('P36', 'the 64-bit ISA read refuses position n', P, 'if ((ulong)position > (ulong)_n)\n        {\n            if (_mapped) throw new InvalidDataException($"the inverse suffix array is read at position {position}, but the text has {_n} symbols: the file is damaged");\n            throw new ArgumentOutOfRangeException(nameof(position));\n        }\n        return GetIsa(member)', 'if ((ulong)position >= (ulong)_n)\n        {\n            if (_mapped) throw new InvalidDataException($"the inverse suffix array is read at position {position}, but the text has {_n} symbols: the file is damaged");\n            throw new ArgumentOutOfRangeException(nameof(position));\n        }\n        return GetIsa(member)', F_PACK)
m('P37', 'the 32-bit ISA read refuses position n', P, 'if ((uint)position > (uint)_n32)\n        {\n            if (_mapped) throw new InvalidDataException($"the inverse suffix array is read at position {position}, but the text has {_n} symbols: the file is damaged");\n            throw new ArgumentOutOfRangeException(nameof(position));\n        }\n        return _isaBuf[position];', 'if ((uint)position >= (uint)_n32)\n        {\n            if (_mapped) throw new InvalidDataException($"the inverse suffix array is read at position {position}, but the text has {_n} symbols: the file is damaged");\n            throw new ArgumentOutOfRangeException(nameof(position));\n        }\n        return _isaBuf[position];', F_PACK)
m('P38', 'the inverse suffix array is built over n entries, not n + 1', P, 'isa = BuildIsaOf(_sa64, checked((int)(_n + 1)));', 'isa = BuildIsaOf(_sa64, checked((int)_n));', F_PACK)
m('P39', 'the scatter of the inverse suffix array does not check for a duplicate', P, 'if ((ulong)position >= (ulong)count || isaBuf[checked((int)position)] != -1)', 'if ((ulong)position >= (ulong)count)', F_PACK)
m('P40', 'the scatter accepts the position n + 1 (the bound is one too wide)', P, 'if ((ulong)position >= (ulong)count || isaBuf[checked((int)position)] != -1)', 'if ((ulong)position > (ulong)count || isaBuf[checked((int)position)] != -1)', F_PACK)
m('P41', 'the policy: PSI is read in place only above InPlaceFrom, not at it', P, 'bool viaPsi = sections.Psi is not null && (index.TextLength >= sections.InPlaceFrom || index.TextLength > PackHeapLimit);', 'bool viaPsi = sections.Psi is not null && (index.TextLength > sections.InPlaceFrom || index.TextLength > PackHeapLimit);', F_PACK)
m('P42', 'the policy: PSI is read in place from one symbol below InPlaceFrom', P, 'bool viaPsi = sections.Psi is not null && (index.TextLength >= sections.InPlaceFrom || index.TextLength > PackHeapLimit);', 'bool viaPsi = sections.Psi is not null && (index.TextLength >= sections.InPlaceFrom - 1 || index.TextLength > PackHeapLimit);', F_PACK)
m('P43', 'the policy: PSI is ignored above the heap limit', P, 'bool viaPsi = sections.Psi is not null && (index.TextLength >= sections.InPlaceFrom || index.TextLength > PackHeapLimit);', 'bool viaPsi = sections.Psi is not null && index.TextLength >= sections.InPlaceFrom && index.TextLength <= PackHeapLimit;', F_PACK)
m('P44', 'the heap array is built for a container of exactly PackHeapLimit symbols no more', P, 'else if (index.TextLength <= PackHeapLimit) isa = BuildIsaOf(PosSource.Of(sa), count);', 'else if (index.TextLength < PackHeapLimit) isa = BuildIsaOf(PosSource.Of(sa), count);', F_PACK)
m('P45', 'the narrow pack with no PSI and no array is linkable', P, '_linkable = viaPsi || isa is not null;', '_linkable = true;', F_PACK)
m('P46', 'Checked: the verification of PSI is off in the narrow pack', P, '_verifyPsi = sections.IsChecked;', '_verifyPsi = false;', F_PACK)
# ---- the 32-bit kernel
m('P50', '32-bit link: the endpoint a is read at the right bound', P, 'a = _psiBuf[node.Lb];\n            b = _psiBuf[node.Rb];', 'a = _psiBuf[node.Rb];\n            b = _psiBuf[node.Rb];', F_PACK)
m('P51', '32-bit link: the endpoint b is read at the left bound', P, 'a = _psiBuf[node.Lb];\n            b = _psiBuf[node.Rb];', 'a = _psiBuf[node.Lb];\n            b = _psiBuf[node.Lb];', F_PACK)
m('P52', '32-bit link: the verification of a compares with the position', P, 'if (_verifyPsi && (sa[a] != node.Pos + 1 || sa[b] != sa[node.Rb] + 1)) throw DamagedNode();', 'if (_verifyPsi && (sa[a] != node.Pos || sa[b] != sa[node.Rb] + 1)) throw DamagedNode();', F_PACK)
m('P53', '32-bit link: b is not verified', P, 'if (_verifyPsi && (sa[a] != node.Pos + 1 || sa[b] != sa[node.Rb] + 1)) throw DamagedNode();', 'if (_verifyPsi && (sa[a] != node.Pos + 1)) throw DamagedNode();', F_PACK)
m('P54', '32-bit link: the PSI range check lets n + 1 through', P, 'if (_mapped && ((uint)a > (uint)_n32 || (uint)b > (uint)_n32)) throw DamagedNode();', 'if (_mapped && ((uint)a > (uint)_n32 + 1 || (uint)b > (uint)_n32)) throw DamagedNode();', F_PACK)
m('P55', '32-bit link: the bounds of the node are not checked', P, 'if (_mapped && ((uint)node.Rb > (uint)_n32 || (uint)node.Lb > (uint)_n32)) throw DamagedNode();\n            a = _psiBuf[node.Lb];', 'a = _psiBuf[node.Lb];', F_PACK)
m('P56', '32-bit link: the borders use the depth instead of depth - 1', P, '_pyramid!.Borders(a, b, t, out int left, out int right, out int leftValue, out int rightValue);', '_pyramid!.Borders(a, b, node.Depth, out int left, out int right, out int leftValue, out int rightValue);', F_PACK)
m('P57', '32-bit link: the interval ends at the right border', P, 'return new EsaNode(left, right - 1, t, parentDepth, target, leftValue > rightValue);', 'return new EsaNode(left, right, t, parentDepth, target, leftValue > rightValue);', F_PACK)
m('P58', '32-bit link: the target position is the left bound', P, 'int target = sa[left];\n        if (_mapped && (uint)target > (uint)_n32) throw DamagedNode();', 'int target = left;\n        if (_mapped && (uint)target > (uint)_n32) throw DamagedNode();', F_PACK)
m('P59', '32-bit link: a parent depth of t passes', P, 'if (_mapped && (parentDepth >= t || (uint)left > (uint)_n32)) throw DamagedNode(); // the target', 'if (_mapped && (parentDepth > t || (uint)left > (uint)_n32)) throw DamagedNode(); // the target', F_PACK)
m('P60', '32-bit leaf link: the PSI rank is not verified', P, 'if (_verifyPsi && _saBuf[rank] != position + 1) throw DamagedNode();', '', F_PACK)
m('P61', '32-bit leaf link: the leaf of the last suffix links to a leaf', P, 'if (position >= _n32) return Root; // the terminator-only leaf of the root', 'if (position > _n32) return Root; // the terminator-only leaf of the root', F_PACK)
m('P62', '32-bit leaf link reads PSI at the position', P, 'rank = _psiBuf[leaf.Lb];', 'rank = _psiBuf[position];', F_PACK)
# ---- Parent, Lcp, Lca
m('P70', 'Parent: the borders use the node depth', P, '_ranges.Borders(node.Lb, node.Rb, parentDepth, out long left, out long right, out long leftValue, out long rightValue);', '_ranges.Borders(node.Lb, node.Rb, node.Depth, out long left, out long right, out long leftValue, out long rightValue);', F_PACK)
m('P71', 'Parent: the interval ends at the right border', P, 'return new EsaNode64(left, right - 1, parentDepth, Math.Max(leftValue, rightValue), left >= 0 && left <= _n ? _sa64[left] : -1, leftValue > rightValue);', 'return new EsaNode64(left, right, parentDepth, Math.Max(leftValue, rightValue), left >= 0 && left <= _n ? _sa64[left] : -1, leftValue > rightValue);', F_PACK)
m('P72', 'Parent of a node of parent depth 0 is not the root', P, 'if (parentDepth == 0) return Root64;\n        _ranges.Borders', 'if (parentDepth == 1) return Root64;\n        _ranges.Borders', F_PACK)
m('P73', 'Lcp of equal ranks is the range minimum', P, 'if (rankA == rankB) return _n - _sa64[rankA];\n        return _ranges.Min', 'if (rankA == rankB) return _n - _sa64[rankA] + 1;\n        return _ranges.Min', F_PACK)
m('P74', 'Lcp of two ranks starts the range at the smaller rank', P, 'return _ranges.Min(Math.Min(rankA, rankB) + 1, Math.Max(rankA, rankB));', 'return _ranges.Min(Math.Min(rankA, rankB), Math.Max(rankA, rankB));', F_PACK)
m('P75', 'Lcp of two ranks ends the range one early', P, 'return _ranges.Min(Math.Min(rankA, rankB) + 1, Math.Max(rankA, rankB));', 'return _ranges.Min(Math.Min(rankA, rankB) + 1, Math.Max(rankA, rankB) - 1);', F_PACK)
m('P76', 'Lca of equal ranks has the depth of the suffix without the terminator', P, 'long depth = _n - _sa64[rankA] + 1;\n            return (rankA, rankA, depth);', 'long depth = _n - _sa64[rankA];\n            return (rankA, rankA, depth);', F_PACK)
m('P77', 'Lca: a value of 0 is not the root', P, 'if (value == 0) return (0, _n, 0);', 'if (value == 1) return (0, _n, 0);', F_PACK)
m('P78', 'Lca: the left border is searched from hi', P, 'return (_ranges.PrevLess(lo, value), _ranges.NextLess(hi + 1, value) - 1, value);', 'return (_ranges.PrevLess(hi, value), _ranges.NextLess(hi + 1, value) - 1, value);', F_PACK)
m('P79', 'Lca: the right border is searched from hi', P, 'return (_ranges.PrevLess(lo, value), _ranges.NextLess(hi + 1, value) - 1, value);', 'return (_ranges.PrevLess(lo, value), _ranges.NextLess(hi, value) - 1, value);', F_PACK)
m('P80', 'Lca: the minimum range starts at lo', P, 'long value = _ranges.Min(lo + 1, hi);', 'long value = _ranges.Min(lo, hi);', F_PACK)
m('P81', 'Lca of the empty text is not the root', P, 'if (_n == 0) return (0, 0, 0);', 'if (_n == 0) return (0, 1, 0);', F_PACK)
m('P82', 'the linkable test: a long pack is never linkable', P, 'internal bool IsLinkable => _linkable || !_narrow;', 'internal bool IsLinkable => _linkable;', F_PACK)
m('P83', 'PayloadBytes counts the ISA at 8 bytes per entry', P, 'internal long PayloadBytes => (4L * (Volatile.Read(ref _isa)?.Length ?? 0)) + _ranges.LevelBytes;', 'internal long PayloadBytes => (8L * (Volatile.Read(ref _isa)?.Length ?? 0)) + _ranges.LevelBytes;', F_PACK)
m('P84', 'the long pack: PSI is not verified', P, '_verifyPsi = verifyPsi && psi is not null;', '_verifyPsi = false;', F_PACK)
m('P85', 'Build picks the RMQ fanout of the section: the default fanout is used instead', P, 'int pyramidFanout = sections.Rmq is null ? fanout : sections.Fanout;', 'int pyramidFanout = fanout;', F_PACK)

W = 'WideLcpPyramid.cs'
m('W01', 'the level size is the floor of the division', W, 'size = (size + fanout - 1) / fanout;', 'size = size / fanout;', F_PYR)
m('W02', 'the level offset does not advance by the level size', W, '_offset[levels] = total;\n                _count[levels] = size;\n                total += size;', '_offset[levels] = total;\n                _count[levels] = size;\n                total += size - 1;', F_PYR)
m('W03', 'the persisted section may hold one entry more than the levels', W, 'if (persisted.Count != total) throw', 'if (persisted.Count < total) throw', F_PYR)
m('W04', 'the persisted section may hold one entry less than the levels', W, 'if (persisted.Count != total) throw', 'if (persisted.Count > total) throw', F_PYR)
m('W05', 'the level array is allowed one entry beyond the array limit', W, 'if (total > Array.MaxLength) throw', 'if (total > Array.MaxLength + 1) throw', F_PYR, STAGE3)
m('W06', 'the first level takes blocks of fanout - 1 entries', W, 'long end = Math.Min(_length, start + f);\n            long min = long.MaxValue;\n            for (long j = start; j < end; j++) min = Math.Min(min, _lcp[j]);\n            _built![b] = min;', 'long end = Math.Min(_length, start + f - 1);\n            long min = long.MaxValue;\n            for (long j = start; j < end; j++) min = Math.Min(min, _lcp[j]);\n            _built![b] = min;', F_PYR)
m('W07', 'the upper level takes the maximum of the level below', W, 'for (long j = start; j < end; j++) min = Math.Min(min, _built![below + j]);', 'for (long j = start; j < end; j++) min = Math.Max(min, _built![below + j]);', F_PYR)
m('W08', 'the upper level starts one block late', W, 'long start = b * f;\n                long end = Math.Min(belowCount, start + f);', 'long start = (b * f) + 1;\n                long end = Math.Min(belowCount, start + f);', F_PYR)
