m('W11', 'Min: the first partial block ends one entry early', W, 'for (long j = lo, end = lo | (f - 1); j <= end; j++) min = Math.Min(min, _lcp[j]);\n        for (long j = hi & ~(f - 1); j <= hi; j++)', 'for (long j = lo, end = (lo | (f - 1)) - 1; j <= end; j++) min = Math.Min(min, _lcp[j]);\n        for (long j = hi & ~(f - 1); j <= hi; j++)', F_PYR)
m('W12', 'Min: the last partial block starts one entry late', W, 'for (long j = hi & ~(f - 1); j <= hi; j++) min = Math.Min(min, _lcp[j]);\n\n        // the whole blocks', 'for (long j = (hi & ~(f - 1)) + 1; j <= hi; j++) min = Math.Min(min, _lcp[j]);\n\n        // the whole blocks', F_PYR)
